import os
import django
from django.conf import settings
from django.http import HttpResponse
from django.urls import path, resolve
from django.views import View
from pickle import dumps, loads

# Configure Django settings
if not settings.configured:
    settings.configure(
        SECRET_KEY='test',
        ROOT_URLCONF=__name__,
    )
    django.setup()

def my_fbv(request):
    return HttpResponse('yay')

class MyView(View):
    def get(self, request):
        return HttpResponse('yay')

urlpatterns = [
    path('fbv/', my_fbv, name='my_fbv'),
    path('cbv/', MyView.as_view(), name='my_cbv'),
]

def test_pickle_fbv():
    print("Testing FBV pickling...")
    try:
        match = resolve('/fbv/')
        pickled = dumps(match)
        unpickled = loads(pickled)
        print("FBV pickling successful!")
        return True
    except Exception as e:
        print(f"FBV pickling failed: {e}")
        return False

def test_pickle_cbv():
    print("Testing CBV pickling...")
    try:
        match = resolve('/cbv/')
        pickled = dumps(match)
        unpickled = loads(pickled)
        print("CBV pickling successful!")
        return True
    except Exception as e:
        print(f"CBV pickling failed: {e}")
        return False

if __name__ == "__main__":
    fbv_ok = test_pickle_fbv()
    cbv_ok = test_pickle_cbv()

    if fbv_ok and cbv_ok:
        print("Both FBV and CBV pickling successful.")
    elif fbv_ok and not cbv_ok:
        print("FBV pickling successful, but CBV pickling failed.")
    elif not fbv_ok and cbv_ok:
        print("FBV pickling failed, but CBV pickling successful.")
    else:
        print("Both FBV and CBV pickling failed.")
